-- =====================================================================
-- SIGAF · Carga · 032 · Fecha REAL de pago y pedido-recepción (N_AP_IMSS_4007, pagos ene–29/10/2026)
-- Fecha: 29/10/2026
-- El 4007 trae los comprobantes PAGADOS que vienen de pedido (PREI: integrales, cuadro básico, etc.) con su
-- fecha de pago real, el número de pedido y el de recepción. Se tomaron solo los de la UI 010102 (HGZ 2,
-- según la unidad de la recepción): 1,286 comprobantes, cada uno con un solo pedido-recepción.
-- Para cada factura de SIGAF con ese CR:
--   · fecha_pago  = fecha real de pago (hoy muchas tienen la fecha PROGRAMADA del 1043)
--   · Gasto reflejado si todavía estaba en trámite (solo avanza)
--   · numero_pedido / numero_recepcion: se llenan si están vacíos (si ya traen otro número NO se cambia;
--     esos salen en la segunda consulta para revisarlos)
--   · estatus_pedido_recepcion = generado
-- Lo que NO viene de pedido (compra emergente, subrogados, fondo fijo) no está en el 4007: su fecha real
-- de pago sale del N_AP_IMSS_4006.
-- Cómo: SQL Editor → Run. Muestra cuántas facturas cambiaron. Después corre la 033 para ver los pedidos distintos.
-- =====================================================================
drop table if exists t4007;
create temp table t4007 (cr text primary key, fecha_pago date, pedido text, recepcion text);
;

with upd as (
  update facturas f set
    fecha_pago               = t.fecha_pago,
    estatus_general          = case when f.estatus_general in ('enviada_ooad','en_tramite_ooad') then 'gasto_reflejado' else f.estatus_general end,
    numero_pedido            = coalesce(nullif(btrim(f.numero_pedido), ''), t.pedido),
    numero_recepcion         = coalesce(nullif(btrim(f.numero_recepcion), ''), t.recepcion),
    estatus_pedido_recepcion = 'generado'
  from t4007 t
  where ltrim(btrim(f.cr_contrarecibo), '0') = t.cr
    and f.anulada = false and f.estatus_general <> 'devuelta_proveedor'
    and (f.fecha_pago is distinct from t.fecha_pago
         or f.estatus_general in ('enviada_ooad','en_tramite_ooad')
         or nullif(btrim(f.numero_pedido), '') is null or nullif(btrim(f.numero_recepcion), '') is null
         or f.estatus_pedido_recepcion is distinct from 'generado')
  returning f.id
)
select count(*) as facturas_actualizadas from upd;
